nta.declaration:
// WashiOS task-health-gated independent watchdog (IWDG), timed-automata model.
// Sources: core/include/core/TaskHealth.hpp, core/include/core/Watchdog.hpp,
// core/include/core/WatchdogRunner.hpp, core/src/main.cpp (G431 build).
// Time unit: 1 ms.

const int HB = 0;   // HeartbeatTask (critical)
const int PL = 1;   // PayloadLinkTask (critical; TaskId aliases TelemetryTaskId)

const int PERIOD[2]   = { 500, 100 };    // HeartbeatTask vTaskDelay; PayloadLinkTask::HealthPeriodMs
const int DEADLINE[2] = { 1500, 800 };   // HeartbeatDeadlineMs; TelemetryDeadlineMs
const int WD_POLL_MS  = 100;   // WatchdogPollPeriodMs (WatchdogRunner::runOnce)
const int WD_TASK_MS  = 50;    // WatchdogTaskDelayMs (WatchdogTask loop)
const int JITTER_MS   = 2;     // RTOS wakeup jitter bound (assumption A1)

// IWDG: LSI ~32 kHz / prescaler 16 = 2 kHz; reload 3999 -> 2000 ms nominal.
// LSI tolerance bracket (assumption A3): reset may come as early as IWDG_MIN_MS and
// no later than IWDG_MAX_MS after the last refresh.
const int IWDG_NOMINAL_MS = 2000;
const int IWDG_MIN_MS     = 1400;
const int IWDG_MAX_MS     = 2600;

// SCENARIO 0: no stall ever (spurious-reset check). SCENARIO 1: one stall may be injected.
const int SCENARIO = 1;

// Shared state
clock since[2];             // time since last check-in of each task (TaskHealthEntry.lastCheckInMs)
bool  healthy[2] = { true, true };   // TaskHealthEntry.healthy
bool  stalled[2] = { false, false };
bool  criticalFailed = false;        // WatchdogTimeout + SafeFail recorded (once)
bool  refreshedAfterFailure = false;
bool  resetHappened = false;

chan stall[2];
chan kick;                  // HAL_IWDG_Refresh

template.declaration:
clock w;   // WatchdogRunner period clock

void markFailure(bool hbExpired, bool plExpired) {
    // TaskHealthRegistry::evaluate (TaskHealth.hpp:96-115): expired entries become
    // unhealthy; the first newly reported failure makes Watchdog::poll record
    // WatchdogTimeout and SafeFail (Watchdog.hpp:42-58).
    if (hbExpired) healthy[HB] = false;
    if (plExpired) healthy[PL] = false;
    criticalFailed = true;
}
void refresh() {
    // Watchdog::poll refresh gate (Watchdog.hpp:61-65)
    if (criticalFailed) refreshedAfterFailure = true;
}

nta.system:
S  = Supervisor();
T0 = Task(HB);
T1 = Task(PL);
W  = Iwdg();
E  = Env();
system S, T0, T1, W, E;
